#!/bin/bash
set -e
cd "$GITHUB_WORKSPACE"
API="https://api.github.com/repos/blackprm/minis-cloud-shell"
AUTH="Authorization: Bearer $GH_TOKEN"

echo "== install ffmpeg =="
sudo apt-get update -qq >/dev/null 2>&1 || true
sudo apt-get install -y -qq ffmpeg >/dev/null 2>&1
which ffprobe

echo "== restore audio =="
cat > audio.b64 <<'AUDIO_EOF'

AUDIO_EOF
base64 -d audio.b64 > /tmp/audio.m4a
ls -la /tmp/audio.m4a

echo "== download artifact =="
curl -sL --retry 3 -H "$AUTH" -o art.zip "$API/actions/artifacts/12604738551/zip"
rm -rf unz && mkdir unz && cd unz && unzip -o ../art.zip >/dev/null
find . -type f -exec ls -la {} \;
VID=$(find . -type f -name '*.mp4' | head -1)
echo "video: $VID"
ffprobe -v error -show_entries format=duration,size,bit_rate -show_entries stream=codec_name,width,height,r_frame_rate "$VID"

echo "== mux audio =="
ffmpeg -y -i "$VID" -i /tmp/audio.m4a -c:v copy -c:a aac -b:a 192k -shortest /tmp/nvda_kline_v2.mp4 2>&1 | tail -2
ffprobe -v error -show_entries format=duration /tmp/nvda_kline_v2.mp4

echo "== extract frames =="
for t in 1.0 2.5 5.0 10.0 16.0 22.0 25.5 27.5 28.8; do
  ffmpeg -y -ss $t -i /tmp/nvda_kline_v2.mp4 -frames:v 1 /tmp/fr_$t.jpg 2>/dev/null || true
done
ls -la /tmp/fr_*.jpg || true

echo "== upload to release nvda-v2 =="
cd /tmp
RID=$(curl -s -H "$AUTH" "$API/releases/tags/nvda-v2" | python3 -c "import json,sys;print(json.load(sys.stdin).get('id',''))" 2>/dev/null || true)
if [ -n "$RID" ]; then
  curl -s -X DELETE -H "$AUTH" "$API/releases/$RID" -o /dev/null
  sleep 2
  curl -s -X DELETE -H "$AUTH" "$API/git/refs/tags/nvda-v2" -o /dev/null || true
  sleep 2
fi
curl -s -X POST -H "$AUTH" -H "Accept: application/vnd.github+json" "$API/releases" -d '{"tag_name":"nvda-v2","name":"nvda-v2","body":"nvda v2 full"}' -o rel.json
UP=$(python3 -c "import json;d=json.load(open('rel.json'));print((d.get('upload_url') or '').split('{')[0])")
if [ -z "$UP" ]; then echo RELEASE_FAIL; cat rel.json; exit 1; fi
curl -s -X POST -H "$AUTH" -H "Content-Type: application/octet-stream" --data-binary @/tmp/nvda_kline_v2.mp4 "$UP?name=nvda_kline_v2.mp4" -o up1.json
python3 -c "import json;d=json.load(open('up1.json'));print('mp4:',d.get('name'),d.get('size'))"
for f in /tmp/fr_*.jpg; do
  n=$(basename $f)
  curl -s -X POST -H "$AUTH" -H "Content-Type: application/octet-stream" --data-binary @"$f" "$UP?name=$n" -o /dev/null
done
echo "== assets =="
curl -s -H "$AUTH" "$API/releases/tags/nvda-v2" | python3 -c "import json,sys; [print(a['name'],a['size']) for a in json.load(sys.stdin).get('assets',[])]"
echo "DONE"
